import{_ as e,c as r,o as n,a4 as t}from"./chunks/framework.BU14wsQo.js";const o="/ai/daily/2026-08-02/news_01kz055c7qenebmga9bf9xeaqx.avif",s="/ai/daily/2026-08-02/news_01kz055fbsenebmgapwq8gkff8.avif",i="/ai/daily/2026-08-02/news_01kz055jc5enebmgayq4hz2r55.avif",f=JSON.parse('{"title":"AI大事件 2026/8/2","description":"2026-08-02 AI大事件：MiniMax H3、Seedance 2.5、TRAE 模板库、Qwen-UI-Agent、OpenAI 十项数学证明、Suno 版权判决与开发者工具更新","frontmatter":{"linkTitle":"08-02 AI大事件","title":"AI大事件 2026/8/2","weight":30,"breadcrumbs":false,"comments":true,"description":"2026-08-02 AI大事件：MiniMax H3、Seedance 2.5、TRAE 模板库、Qwen-UI-Agent、OpenAI 十项数学证明、Suno 版权判决与开发者工具更新"},"headers":[],"relativePath":"ai/daily/cn/2026-08/2026-08-02.md","filePath":"AI/daily/cn/2026-08/2026-08-02.md","lastUpdated":1785716471000}'),l={name:"ai/daily/cn/2026-08/2026-08-02.md"};function h(c,a,p,d,g,b){return n(),r("div",null,[...a[0]||(a[0]=[t(`<h1 align="center">2026-08-02 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MiniMax H3 与 Seedance 2.5 把多模态生成继续推向音画一体和更长视频 🚀</span></span>
<span class="line"><span>Qwen-UI-Agent、ACE、Frontis 与 VideoCoCo 集中刷新智能体、具身数据和视频物理生成方法 🧠</span></span>
<span class="line"><span>OpenAI 公开十项数学证明与 Lean 4 证书，形式化验证成为大模型成果的新锚点 ( •̀ ω •́ )</span></span>
<span class="line"><span>Suno 在德国版权诉讼中遭遇不利裁定，训练与输出责任边界继续收紧 ⚖️</span></span>
<span class="line"><span>微软、腾讯和语音工具项目继续占据开源热度，开发者学习与记忆基础设施升温 🛠️</span></span>
<span class="line"><span>Grok 语音跑分和持久工作区研究说明，智能体体验正在从单次回答转向可恢复任务 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-minimax-升级全模态" tabindex="-1">1. MiniMax 升级全模态 <a class="header-anchor" href="#_1-minimax-升级全模态" aria-label="Permalink to &quot;1. MiniMax 升级全模态&quot;">​</a></h3><p><strong>MiniMax H3</strong> 正式上线，模型可统一读取图文、音频与视频，并输出 2K 原生立体声音视频内容。单片时长覆盖 4 到 15 秒，产品重点从单纯视频生成扩展到更完整的全模态创作链路，适合广告短片、角色展示和多素材合成场景 🚀。来源：<a href="https://www.minimax.io/blog/minimax-h3" target="_blank" rel="noreferrer">全模态视频模型说明</a></p><h3 id="_2-seedance-音画同生" tabindex="-1">2. Seedance 音画同生 <a class="header-anchor" href="#_2-seedance-音画同生" aria-label="Permalink to &quot;2. Seedance 音画同生&quot;">​</a></h3><p><strong>Seedance 2.5</strong> 继续强化视频生成，单段视频最长达到 30 秒，并支持画面与音频同步生成。这个方向的关键不是“更长”本身，而是把配乐、环境声和画面节奏放进同一生成链路，短视频制作的后期拼接成本会明显下降 🎬。来源：<a href="https://the-decoder.com/bytedances-seedance-2-5-generates-30-second-video-clips-with-built-in-audio/" target="_blank" rel="noreferrer">字节视频模型发布详情</a></p><h3 id="_3-trae-模板库正式上线" tabindex="-1">3. TRAE 模板库正式上线 <a class="header-anchor" href="#_3-trae-模板库正式上线" aria-label="Permalink to &quot;3. TRAE 模板库正式上线&quot;">​</a></h3><p><strong>TRAE Work</strong> 模板库上线，覆盖十类工作流和上百套模板，用户可先预览真实输出，再收藏模板并创建任务。对团队协作来说，这类模板库的价值在于把“提示词灵感”沉淀成可复用入口，降低从空白任务启动的摩擦 (^_^)v。来源：<a href="https://x.com/Trae_ai/status/2083404521410097401" target="_blank" rel="noreferrer">模板上线动态原文</a></p><p><img src="`+o+'" alt="AI资讯：TRAE Work模板库界面展示百套创作模板" loading="lazy"></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-千问智能体操控真机" tabindex="-1">1. 千问智能体操控真机 <a class="header-anchor" href="#_1-千问智能体操控真机" aria-label="Permalink to &quot;1. 千问智能体操控真机&quot;">​</a></h3><p><strong>Qwen-UI-Agent</strong> 面向真实设备环境，把界面动作与命令行动作合并到同一动作空间。技术报告显示，它在安卓日常基准达到 97.5%，并通过万级环境训练百轮长任务；这让“会看屏幕”进一步走向“能稳定操作设备” 🖥️。来源：<a href="https://huggingface.co/papers/2607.28227" target="_blank" rel="noreferrer">千问智能体技术报告</a></p><p><img src="'+s+'" alt="AI资讯：千问界面智能体跨手机电脑执行长程任务" loading="lazy"></p><h3 id="_2-ace-补齐具身数据" tabindex="-1">2. ACE 补齐具身数据 <a class="header-anchor" href="#_2-ace-补齐具身数据" aria-label="Permalink to &quot;2. ACE 补齐具身数据&quot;">​</a></h3><p><strong>ACE</strong> 把家庭空间改造成同步录制场，采集 150 小时演示数据，覆盖两百类家庭活动。它把触觉、声音、画面和轨迹统一对齐，目标是解决具身智能最稀缺的高质量真实交互数据问题；视频素材源下载不稳定，本条仅保留正文与来源，避免引用残缺媒体。来源：<a href="https://huggingface.co/papers/2607.28625" target="_blank" rel="noreferrer">具身数据引擎论文</a></p><h3 id="_3-frontis-迈向自我改进" tabindex="-1">3. Frontis 迈向自我改进 <a class="header-anchor" href="#_3-frontis-迈向自我改进" aria-label="Permalink to &quot;3. Frontis 迈向自我改进&quot;">​</a></h3><p><strong>Frontis</strong> 是面向机器学习工程的 35B 模型，训练过程引入执行搜索，让模型能在任务预算内形成“提出方案、运行、评估、改进”的闭环。论文给出的单卡任务预算为十二小时，最终成绩升至 71.21%，显示自动化 ML 工程正在向可递归优化靠近 🧪。来源：<a href="https://huggingface.co/papers/2607.28568" target="_blank" rel="noreferrer">递归改进模型论文详情</a></p><h3 id="_4-代码锁定视频物理" tabindex="-1">4. 代码锁定视频物理 <a class="header-anchor" href="#_4-代码锁定视频物理" aria-label="Permalink to &quot;4. 代码锁定视频物理&quot;">​</a></h3><p><strong>VideoCoCo</strong> 为视频生成引入代码思维链，代理先生成可执行仿真程序，再用三维草稿锁定时空变化。它的重点是让模型先“算清楚运动”，再生成画面；两项视频基准刷新成绩，说明物理一致性仍是视频模型竞争的核心指标 ( •̀ ω •́ )。来源：<a href="https://huggingface.co/papers/2607.27380" target="_blank" rel="noreferrer">物理视频生成论文主页</a></p><p><img src="'+i+'" alt="AI资讯：VideoCoCo通过Blender代码控制视频物理运动" loading="lazy"></p><h3 id="_5-openai-公开十项证明" tabindex="-1">5. OpenAI 公开十项证明 <a class="header-anchor" href="#_5-openai-公开十项证明" aria-label="Permalink to &quot;5. OpenAI 公开十项证明&quot;">​</a></h3><p><strong>OpenAI</strong> 公开十项数学与理论计算机科学成果，覆盖群论、von Neumann 代数、量子复杂度、高维球堆积和电路复杂度等方向，并同步开放形式化证明代码仓库。全部成果用 Lean 4 验证，意味着模型生成的研究结果正被推向可检查、可复现的证明资产 🧮。来源：<a href="https://openai.com/index/ten-advances-in-mathematics/" target="_blank" rel="noreferrer">十项数学成果官方说明</a>、<a href="https://github.com/openai/ten-proofs" target="_blank" rel="noreferrer">形式化证明代码仓库</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-奥特曼复盘-sora-取舍" tabindex="-1">1. 奥特曼复盘 Sora 取舍 <a class="header-anchor" href="#_1-奥特曼复盘-sora-取舍" aria-label="Permalink to &quot;1. 奥特曼复盘 Sora 取舍&quot;">​</a></h3><p>奥特曼在产品路线访谈中复盘 <strong>Sora</strong> 取舍：短视频沉浸体验影响了早期判断，而代码智能体的进展正在改写资源排序。对 OpenAI 来说，更多算力转向通用智能并不只是技术选择，也是在重新评估哪类产品最接近长期复利 📱。来源：<a href="https://www.qbitai.com/2026/08/464713.html" target="_blank" rel="noreferrer">奥特曼产品路线访谈</a></p><h3 id="_2-李飞飞押注物理世界模型" tabindex="-1">2. 李飞飞押注物理世界模型 <a class="header-anchor" href="#_2-李飞飞押注物理世界模型" aria-label="Permalink to &quot;2. 李飞飞押注物理世界模型&quot;">​</a></h3><p>围绕 <strong>World Labs</strong> 与无问智科的报道显示，李飞飞团队继续押注物理世界模型，收购 SceniX 并推动 R2S2R 把真机任务搬进仿真。这个“三世界闭环”的核心，是让策略先在虚拟场景中反复试错，再回到真实机器人任务 🛠️。来源：<a href="https://www.qbitai.com/2026/08/464532.html" target="_blank" rel="noreferrer">量子位深度报道原文速览</a></p><h3 id="_3-德国法院裁定-suno-侵权" tabindex="-1">3. 德国法院裁定 Suno 侵权 <a class="header-anchor" href="#_3-德国法院裁定-suno-侵权" aria-label="Permalink to &quot;3. 德国法院裁定 Suno 侵权&quot;">​</a></h3><p>慕尼黑法院裁定 <strong>Suno</strong> 在训练过程及输出结果中侵犯版权，并驳回其合理使用抗辩。法院认为 Suno 3.5 和 4 版本模型可复现六首知名歌曲的原创元素，构成“记忆化”侵权，且责任归于 Suno 而非用户；该案尚未形成最终生效判决，但已经给音乐生成模型的训练边界敲响警钟 ⚖️。来源：<a href="https://the-decoder.com/german-court-rules-ai-music-generator-suno-violated-copyrights-rejects-fair-use-defense/" target="_blank" rel="noreferrer">人工智能音乐版权裁定</a></p><h3 id="_4-uber-扩张自动驾驶版图" tabindex="-1">4. Uber 扩张自动驾驶版图 <a class="header-anchor" href="#_4-uber-扩张自动驾驶版图" aria-label="Permalink to &quot;4. Uber 扩张自动驾驶版图&quot;">​</a></h3><p><strong>Uber</strong> 过去两年牵手三十余家自动驾驶伙伴，合作覆盖投资、车辆部署和机器人出租车运营。合作名单里 Waymo 与 NVIDIA 仍占据核心位置，Lucid 订单升至 3.5 万辆，说明自动驾驶商业化正在从单点试运营转向平台级网络整合 🚕。来源：<a href="https://techcrunch.com/2026/08/01/ubers-autonomous-vehicle-deal-tracker/" target="_blank" rel="noreferrer">自动驾驶合作版图追踪</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-微软生成式课程走红-🌟114-2k" tabindex="-1">1. 微软生成式课程走红 🌟114.2k <a class="header-anchor" href="#_1-微软生成式课程走红-🌟114-2k" aria-label="Permalink to &quot;1. 微软生成式课程走红 🌟114.2k&quot;">​</a></h3><p><strong>microsoft/generative-ai-for-beginners</strong> 用 21 课降低生成式 AI 入门门槛，仓库累计获得 114.2k 星标，单日新增星标达到 108。它的热度说明开发者仍需要体系化、可实操的课程材料，而不是只看零散模型发布 🛠️。来源：<a href="https://github.com/microsoft/generative-ai-for-beginners" target="_blank" rel="noreferrer">微软生成式入门教程</a></p><h3 id="_2-trellis-降低三维门槛-🌟9-9k" tabindex="-1">2. TRELLIS 降低三维门槛 🌟9.9k <a class="header-anchor" href="#_2-trellis-降低三维门槛-🌟9-9k" aria-label="Permalink to &quot;2. TRELLIS 降低三维门槛 🌟9.9k&quot;">​</a></h3><p><strong>Microsoft TRELLIS.2</strong> 开源三维生成源码，通过结构潜变量压缩三维生成流程，面向游戏资产、产品展示和空间内容制作。项目累计获得 9.9k 星标，三维内容生产正在从专业工具链向模型驱动流程迁移 📐。来源：<a href="https://github.com/microsoft/TRELLIS.2" target="_blank" rel="noreferrer">三维生成项目开源主页</a></p><h3 id="_3-腾讯共享智能体记忆-🌟10-3k" tabindex="-1">3. 腾讯共享智能体记忆 🌟10.3k <a class="header-anchor" href="#_3-腾讯共享智能体记忆-🌟10-3k" aria-label="Permalink to &quot;3. 腾讯共享智能体记忆 🌟10.3k&quot;">​</a></h3><p><strong>TencentDB-Agent-Memory</strong> 关注团队级智能体记忆，沉淀对话、文档、代码和资产，让记忆可在框架之间共享。项目累计获得 10.3k 星标，说明“避免团队遗忘”已经成为智能体落地的工程问题，而不只是聊天体验优化 📚。来源：<a href="https://github.com/TencentCloud/TencentDB-Agent-Memory" target="_blank" rel="noreferrer">腾讯智能体记忆仓库</a></p><h3 id="_4-voice-pro-整合语音工具-🌟11-8k" tabindex="-1">4. voice-pro 整合语音工具 🌟11.8k <a class="header-anchor" href="#_4-voice-pro-整合语音工具-🌟11-8k" aria-label="Permalink to &quot;4. voice-pro 整合语音工具 🌟11.8k&quot;">​</a></h3><p><strong>voice-pro</strong> 集成五套语音引擎，把转写、克隆、合成和音频整理集中到网页端。它结合 Whisper 转写与 Demucs 人声分离，适合把播客、访谈和短视频配音处理放进一个工作台 🎙️。来源：<a href="https://github.com/abus-aikorea/voice-pro" target="_blank" rel="noreferrer">一站式语音工坊项目</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-企业代理走向自进化" tabindex="-1">1. 企业代理走向自进化 <a class="header-anchor" href="#_1-企业代理走向自进化" aria-label="Permalink to &quot;1. 企业代理走向自进化&quot;">​</a></h3><p>一篇自进化智能体研究提出，企业日常工作轨迹可以变成持续训练教材，框架采用三层更新机制：记忆先更新，策略再优化，模型参数最后进入更重的调整。这个思路把智能体从“回答一次”推进到“边工作边积累组织经验” 🔄。来源：<a href="https://arxiv.org/abs/2607.01120v1" target="_blank" rel="noreferrer">自进化智能体研究论文</a></p><h3 id="_2-grok-语音跑分领先" tabindex="-1">2. Grok 语音跑分领先 <a class="header-anchor" href="#_2-grok-语音跑分领先" aria-label="Permalink to &quot;2. Grok 语音跑分领先&quot;">​</a></h3><p>围绕 <strong>Grok</strong> 语音能力的测试显示，它在两百道税务语音题中，文本成绩达到 99%，音频成绩达到 95.7%，语音轮次速度几乎快过对手两倍。这里更值得观察的是实时语音交互的延迟和准确率组合，而不是单个榜单名次 ⚡。来源：<a href="https://x.com/cb_doge/status/2083636690707464615" target="_blank" rel="noreferrer">实时语音跑分原帖</a></p><h3 id="_3-持久工作区补齐断点" tabindex="-1">3. 持久工作区补齐断点 <a class="header-anchor" href="#_3-持久工作区补齐断点" aria-label="Permalink to &quot;3. 持久工作区补齐断点&quot;">​</a></h3><p>持久工作区讨论把问题说得很直接：终端关闭、上下文压缩和跨会话交接都会让团队状态丢失。相关论文提出把智能体任务放进可恢复工作区，减少交接成本；这类基础设施会影响长任务能否真正从演示走向生产 (๑•̀ㅂ•́)و✧。来源：<a href="https://x.com/omarsar0/status/2083662558334996609" target="_blank" rel="noreferrer">持久工作区讨论原帖</a>、<a href="https://arxiv.org/abs/2607.22917" target="_blank" rel="noreferrer">智能体工作区研究论文</a></p><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>多模态生成正在并轨。</strong> MiniMax H3 与 Seedance 2.5 都指向同一个趋势：视频、音频和素材理解不再是分开的功能 🚀。</li><li><strong>研究成果更依赖可检查证据。</strong> OpenAI 的 Lean 4 证明仓库、Qwen-UI-Agent 的设备基准和 VideoCoCo 的仿真程序，都在提高“能复现”的权重 🧠。</li><li><strong>版权风险进入模型训练主战场。</strong> Suno 案把训练责任、输出相似性和合理使用抗辩放到同一张桌上，音乐生成只是第一批承压场景 ⚖️。</li><li><strong>开源热度集中在实用基础设施。</strong> 课程、三维生成、智能体记忆和语音工坊都不是概念项目，而是在补齐开发者真实工作流 🛠️。</li><li><strong>智能体体验开始追求连续性。</strong> 语音实时交互和持久工作区共同说明，下一阶段竞争点会从“单轮聪明”转向“长任务可靠” ( •̀ ω •́ )。</li></ul>',51)])])}const m=e(l,[["render",h]]);export{f as __pageData,m as default};
